import XCTest
@testable import KipurseCore

/// t1268: what the phone key signs must be byte-for-byte what the SERVER verifies. The fixture is generated by the gateway
/// (scripts/t1268-phone-texts-fixture.mjs, from signinKeyDigest + everydayText / everydayDigest); the gateway test fails if it is stale.
final class T1268PhoneTextsCrossTests: XCTestCase {
  struct SigninCase: Decodable { let id, digest: String }
  struct EverydayCase: Decodable { let wallet, single, daily, term, nonce, text, digest: String }
  struct File: Decodable { let signin: [SigninCase]; let everyday: [EverydayCase] }
  func load() throws -> File {
    let u = URL(fileURLWithPath: #filePath).deletingLastPathComponent().appendingPathComponent("t1268-phone-texts.json.txt")
    return try JSONDecoder().decode(File.self, from: Data(contentsOf: u))
  }
  func testSigninKeyDigestEqualsGateway() throws {
    let f = try load(); XCTAssertGreaterThanOrEqual(f.signin.count, 5)
    for c in f.signin {
      XCTAssertTrue(SigninKeyProof.validId(c.id))
      XCTAssertEqual(Hex.encode(SigninKeyProof.digest(id: c.id)).lowercased(), c.digest, c.id)
      XCTAssertTrue(SigninKeyProof.serverDigestMatches(c.digest, id: c.id))
      XCTAssertFalse(SigninKeyProof.serverDigestMatches(c.digest, id: String(c.id.reversed())) && String(c.id.reversed()) != c.id)
    }
  }
  func testEverydayTextAndDigestEqualGateway() throws {
    let f = try load(); XCTAssertGreaterThanOrEqual(f.everyday.count, 15)
    for c in f.everyday {
      let s = Int64(c.single)!, d = Int64(c.daily)!, t = Int64(c.term)!
      XCTAssertEqual(EverydaySign.text(wallet: c.wallet, single: s, daily: d, term: t, nonce: c.nonce), c.text)
      XCTAssertEqual(Hex.encode(EverydaySign.digest(wallet: c.wallet, single: s, daily: d, term: t, nonce: c.nonce)).lowercased(), c.digest)
      XCTAssertNotEqual(Hex.encode(EverydaySign.digest(wallet: c.wallet, single: s, daily: d + 1, term: t, nonce: c.nonce)).lowercased(), c.digest)
    }
  }
  func testNewIdShapeAndRules() {
    let a = SigninKeyProof.newId(), b = SigninKeyProof.newId()
    XCTAssertTrue(SigninKeyProof.validId(a)); XCTAssertNotEqual(a, b)
    XCTAssertFalse(SigninKeyProof.validId("ABCDEF0123456789abcdef0123456789")); XCTAssertFalse(SigninKeyProof.serverDigestMatches(nil, id: a))
    XCTAssertTrue(EverydaySign.signable(single: 1, daily: 1, term: 1)); XCTAssertFalse(EverydaySign.signable(single: 2, daily: 1, term: 5)); XCTAssertFalse(EverydaySign.signable(single: 0, daily: 1, term: 1))
  }
  /// t1268: sign-in status names the wallet's seat / approver; parsed as hints for WalletVerify only (valid addresses, never for "new").
  func testSigninStatusApproverHints() throws {
    let W = "0x2000000000000000000000000000000000000002", O = "0x1000000000000000000000000000000000000003", S = "0x00000000000000000000000000000000000000c5"
    let j = { (s: String) in try JSONDecoder().decode(JSONValue.self, from: Data(s.utf8)) }
    let b = CoinbaseIdentity.Result(try j(#"{"state":"done","result":"bind","owner":"\#(O)","wallet":"\#(W)","seat":"\#(S)","approver":"nope"}"#))
    XCTAssertEqual(b?.approverHints, [S])
    let n = CoinbaseIdentity.Result(try j(#"{"state":"done","result":"new","owner":"\#(O)","wallet":null,"seat":"\#(S)"}"#))
    XCTAssertEqual(n?.approverHints, [])
    let r = CoinbaseIdentity.Result(try j(#"{"state":"done","result":"reconnect","owner":"\#(O)","wallet":"\#(W)"}"#))
    XCTAssertEqual(r?.approverHints, [])
  }
}

/// t1268 (handbook §6#133, locked rule 0A #2): a bind sign-in never prompts Face ID; its key proof is done by turning on Face ID approvals.
final class T1268DeferredProofSourceTests: XCTestCase {
  func src(_ f: String) throws -> String { try String(contentsOfFile: #filePath.replacingOccurrences(of: "Tests/KipurseCoreTests/T1268PhoneTextsCrossTests.swift", with: "App/Sources/" + f), encoding: .utf8) }
  func testBindSavesTheProofInsteadOfFaceID() throws {
    let s = try src("CoinbaseSignIn.swift")
    XCTAssertTrue(s.contains("OwedSigninProof.save(id: p.id, poll: p.poll, digest: p.digest, x: p.x, y: p.y)"))
    XCTAssertFalse(s.contains("await proveOwed()"))
  }
  func testEnrollmentFulfillsItWithTheSameFaceID() throws {
    let s = try src("PhoneSigner.swift")
    XCTAssertEqual(s.components(separatedBy: "OwedSigninProof.fulfill(reason:").count - 1, 2)
  }
}
